INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷78·晋高祖纪·天福四年八月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/edf81ef2a20318750c60f3a1d5fdfb06de275ef4/content/books/zizhi-tongjian/vol-282/year-0939/part-04/sources/library/jiuwudaishi-078-august/source.txt", "note": "《旧五代史》卷78·晋高祖纪·天福四年八月，段落 jiu-wudaishi-205deb4a7860-p001935；已核上下文及传主，纸本及异文待核。", "id": "b6a74ceb-566c-5a3d-903a-fa0e9a29940e"}, {"title": "旧五代史·卷133·马希范传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/edf81ef2a20318750c60f3a1d5fdfb06de275ef4/content/books/zizhi-tongjian/vol-282/year-0939/part-04/sources/library/jiuwudaishi-133-ma-xifan/source.txt", "note": "《旧五代史》卷133·马希范传，段落 jiu-wudaishi-205deb4a7860-p003141；已核上下文及传主，纸本及异文待核。", "id": "59353483-fe28-5a46-841a-f4fc2358b3bc"}, {"title": "资治通鉴·后晋纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/edf81ef2a20318750c60f3a1d5fdfb06de275ef4/content/books/zizhi-tongjian/vol-282/year-0939/part-04/sources/library/tongjian-282-939-autumn/source.txt", "note": "《资治通鉴》后晋纪三，段落 zizhi-tongjian-a63549944a71-p003351；电子底本待考，分段待核", "id": "ae1a99c8-e99c-5cab-8102-be9be479d9f7"}, {"title": "新五代史·卷68·闽世家·王继业亲属校勘注", "source_type": "reference", "author": "电子本校勘注，署名未核", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5efcbcb0eb59aa562545d6da167437d1e8fb96be/content/books/zizhi-tongjian/vol-282/year-0939/part-04/sources/library/xinwudaishi-068-jiye-editorial-note/source.txt", "note": "《新五代史》卷68·闽世家·王继业亲属校勘注，段落 xin-wudaishi-b08f244b9241-p003418；已核上下文及传主，纸本及异文待核。", "id": "36c10533-c67a-52e3-9dca-b6003949037f"}, {"title": "新五代史·卷68·闽世家·宸卫军与政变", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/edf81ef2a20318750c60f3a1d5fdfb06de275ef4/content/books/zizhi-tongjian/vol-282/year-0939/part-04/sources/library/xinwudaishi-068-min-mutiny/source.txt", "note": "《新五代史》卷68·闽世家·宸卫军与政变，段落 xin-wudaishi-b08f244b9241-p003405；已核上下文及传主，纸本及异文待核。", "id": "5eb35093-81c8-5caa-b445-908cae0f0f8f"}, {"title": "新五代史·卷68·闽世家·追杀王继鹏", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/edf81ef2a20318750c60f3a1d5fdfb06de275ef4/content/books/zizhi-tongjian/vol-282/year-0939/part-04/sources/library/xinwudaishi-068-min-pursuit/source.txt", "note": "《新五代史》卷68·闽世家·追杀王继鹏，段落 xin-wudaishi-b08f244b9241-p003406；已核上下文及传主，纸本及异文待核。", "id": "3b385d81-2ce7-5813-a3de-61dee2859af2"}, {"title": "资治通鉴·后晋纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c95625692d30c3a868c0e61b35b6fb0ce80c9c44/content/books/zizhi-tongjian/vol-282/year-0939/part-03/sources/library/tongjian-282-939-intercalary/source.txt", "note": "《资治通鉴》后晋纪三，段落 zizhi-tongjian-a63549944a71-p003350；电子底本待考，分段待核", "id": "b35bc732-9e6a-58d7-bd84-58ffa2046472"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王延钧", "aliases": ["王璘", "王鏻", "王延鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明三年条所见人物：王延钧。", "biography": null, "status": "draft", "id": "5be92fdd-884d-5ecb-b627-4f46ac442676"}, {"name": "王审知", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加封钱镠、张全义、刘隐等”中为受授者。", "biography": null, "status": "draft", "id": "099c16ed-15be-506b-a65f-aa94c272cbd8"}, {"name": "王继鹏", "aliases": ["王繼鵬", "王昶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继鹏，被任命权军府事的王子。", "biography": null, "status": "draft", "id": "94e0308c-1642-5beb-9233-76f848fff4f0"}, {"name": "王继隆", "aliases": ["王繼隆"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王继鹏的堂弟。《资治通鉴》记他在饮酒时失礼，被王继鹏杀死；此事为此前追述，具体年份未载。生年未载。", "biography": null, "status": "draft", "id": "e7c199c8-45de-5de8-a464-549d8035aeb7"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "朱文进", "aliases": ["硃文进", "朱文進", "硃文進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "永泰人，闽国拱宸军将领。《资治通鉴》记他与连重遇多次受王继鹏侮辱而心怀不满，《新五代史》还记二人因宸卫军待遇优厚而激怒部众。生卒年未载。", "biography": null, "status": "draft", "id": "309ef83c-46fe-51a1-86cc-c2cb8dc48d82"}, {"name": "连重遇", "aliases": ["連重遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光山人，闽国控鹤军将领。939年率拱宸、控鹤军起兵攻击王继鹏，拥立王延羲。生卒年未载。", "biography": null, "status": "draft", "id": "5f02df46-1b50-5419-8220-ef50fe37c3eb"}, {"name": "陈郯", "aliases": ["陳郯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国内学士。939年私下告诉连重遇，王继鹏怀疑他与纵火有关、想将他杀死。《新五代史》还记他曾受王继鹏亲信。生卒年未载。", "biography": null, "status": "draft", "id": "db31765c-bc71-5553-9797-31f224cd65e4"}, {"name": "李春燕", "aliases": ["李春鷰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李春燕，宫人、被记与福王私通者。", "biography": null, "status": "draft", "id": "600b7aa1-b6b4-52ad-8ce1-2e5d07e17be5"}, {"name": "王继业", "aliases": ["王繼業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国前汀州刺史。939年受王延羲派遣追赶王继鹏，随后将王继鹏带回并杀死。《资治通鉴》称他为王延羲兄长的儿子，《新五代史》称为王延羲之子，亲属异说暂未裁定。生卒年未载。", "biography": null, "status": "draft", "id": "ba45fd2b-6648-5c10-aed8-a06182d774d7"}, {"name": "王继恭", "aliases": ["王繼恭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，937年以威武节度使身份奉闽王命向后晋报告继位并请求设立邸舍。《资治通鉴》称他为闽王王继鹏的弟弟，《新五代史》称为儿子，亲属身份存在异说。", "biography": null, "status": "draft", "id": "10a53d6a-e6d8-5230-b1aa-76b1340b24f1"}, {"name": "李真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员。939年王延羲即位后，将已以太子太傅身份退休的李真任为司空兼中书侍郎、同平章事。生卒年未载。", "biography": null, "status": "draft", "id": "be8de9d6-a061-55a2-9434-5f7e8c2a8702"}, {"name": "陈守元", "aliases": ["陳守元"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈守元，道士、劝建宫者。", "biography": null, "status": "draft", "id": "5df7e840-5673-57f7-83d7-ba3228fe2d3c"}, {"name": "蔡守蒙", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，任吏部侍郎并负责三司事务。937年在王继鹏逼迫下接受收取贿赂、登记上缴的任官办法。史书称他是候官人，地名写法待核。", "biography": null, "status": "draft", "id": "e782fe72-eb5f-5d36-b118-9f9622a67a46"}, {"name": "林兴（闽国巫者）", "aliases": ["林兴", "林興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国巫者，受王继鹏信任，假托宝皇之命参与政事。939年诬指王延武、王延望谋变，并奉命将二人及其五名子女杀死；同年因骗局败露被流放泉州。《新五代史》另记他后来被杀，具体时间未载。", "biography": null, "status": "draft", "id": "fb411814-4b89-58fe-b422-59b8082ab234"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "钱传瓘", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为出征者。", "biography": null, "status": "draft", "id": "6674e6a1-d66d-5e57-af1f-2d98f55021a1"}, {"name": "彭士愁", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "溪州刺史。939年率蒋州、锦州部众一万多人进攻辰州、澧州，并向后蜀求援，未获同意。生卒年未载。", "biography": null, "status": "draft", "id": "a28c6cdb-75c0-5abc-8757-6d971634ad02"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "刘勍", "aliases": ["劉勍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国左静江指挥使。939年九月与决胜指挥使廖匡齐率衡山兵五千讨伐彭士愁。生卒年未载。", "biography": null, "status": "draft", "id": "f3436028-6ef5-568c-a1c1-0bec76b0ccb3"}, {"name": "廖匡齐", "aliases": ["廖匡齊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：廖匡齐，副指挥使、出斗杀敌者。", "biography": null, "status": "draft", "id": "0d79e8f1-4787-5f81-84cc-50864386544a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "王延钧以王审知的旧部组成拱宸、控鹤军", "start_year": null, "end_year": null, "time_original": "闽国政变以前的追述，具体年份及日期未载", "dynasty": "五代十国", "description": "王延钧以王审知的旧部组成拱宸、控鹤两军。所用《资治通鉴》电子本在句首写按鹤，后文写控鹤；展示采用后文及《新五代史》的控鹤名称，原文保留。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0d51a49b-b6cc-52a0-abe0-3503f319ddbd"}, {"title": "王继鹏另募二千壮士组成宸卫军，给予更厚待遇", "start_year": null, "end_year": null, "time_original": "闽国政变以前的追述，具体年份及日期未载", "dynasty": "五代十国", "description": "王继鹏即位后另募二千壮士作为心腹，称宸卫都，禄赐比拱宸、控鹤两军更优厚。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "34080ab3-1efa-5b00-b42d-ec3218c6f9da"}, {"title": "王继鹏听信两军将作乱的说法，打算分派到漳州、泉州", "start_year": null, "end_year": null, "time_original": "闽国政变以前的追述，具体年份及日期未载", "dynasty": "五代十国", "description": "有人称拱宸、控鹤军因待遇不满而准备作乱。王继鹏打算将两军分派到漳州、泉州，这让两军更加愤怒。", "phases": [], "location_name": "漳州、泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "df7d6836-57bb-5d32-b6d9-11be5993bc15"}, {"title": "王继鹏通宵饮酒、强迫群臣喝酒，并让人寻找他们的过失", "start_year": null, "end_year": null, "time_original": "闽国政变以前的追述，具体年份及日期未载", "dynasty": "五代十国", "description": "王继鹏通宵饮酒、强迫群臣喝酒，并让人寻找他们的过失。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "i